import csv
import math
import re
from datetime import datetime

import numpy as np


def parse_amount(raw: str) -> float:
    s = raw.strip()
    if not s:
        return float('nan')

    is_negative = False
    if 'CR' in s.upper():
        is_negative = True
    elif s.startswith('(') and s.endswith(')'):
        is_negative = True
    elif '-' in s:
        is_negative = True

    s = re.sub(r'C1|C2', '', s, flags=re.IGNORECASE)
    s = re.sub(r'[^0-9,.]', '', s)

    if not s:
        return float('nan')

    has_comma = ',' in s
    has_dot = '.' in s

    if has_comma and has_dot:
        last_comma = s.rindex(',')
        last_dot = s.rindex('.')
        if last_comma > last_dot:
            s = s.replace('.', '')
            s = s.replace(',', '.')
        else:
            s = s.replace(',', '')
    elif has_comma and not has_dot:
        last_comma = s.rindex(',')
        if len(s) - last_comma - 1 == 2:
            s = s.replace(',', '.')
        else:
            s = s.replace(',', '')
    elif has_dot and not has_comma:
        last_dot = s.rindex('.')
        if len(s) - last_dot - 1 != 2:
            s = s.replace('.', '')

    try:
        val = float(s)
    except ValueError:
        return float('nan')

    if is_negative:
        val = -val
    return val


def parse_notes(notes: str) -> tuple:
    items = None
    adj_pct = 0.0
    fee = 0.0
    waive = False

    if not notes:
        return items, adj_pct, fee, waive

    parts = notes.split(';')
    for part in parts:
        part = part.strip()
        if '=' not in part:
            continue
        key, _, val = part.partition('=')
        key = key.strip().lower()
        val = val.strip()

        if key == 'items':
            try:
                items = int(val)
            except ValueError:
                pass
        elif key == 'adj':
            val_clean = val.rstrip('%').strip()
            try:
                adj_pct = float(val_clean)
            except ValueError:
                pass
        elif key == 'fee':
            try:
                fee = float(val)
            except ValueError:
                pass
        elif key == 'waive':
            waive = val.lower() == 'true'

    return items, adj_pct, fee, waive


def robust_z_score(values: list[float]) -> list[float]:
    arr = np.array(values)
    median = np.median(arr)
    mad = np.median(np.abs(arr - median))
    if mad == 0:
        return [0.0] * len(values)
    return list(0.6745 * (arr - median) / mad)


def answer() -> list[str]:
    rows = []
    with open('/app/dataset/data.csv', newline='') as f:
        reader = csv.reader(f)
        headers = next(reader)
        for idx, row in enumerate(reader):
            record_id = row[0]
            event_time_raw = row[1].strip()
            region = row[2].strip()
            channel = row[3].strip().lower()
            amount_str = row[4]
            notes = row[5]

            et = None
            if event_time_raw:
                et = datetime.fromisoformat(event_time_raw.replace('Z', '+00:00'))

            base_amount = parse_amount(amount_str)
            items_val, adj_pct, fee_val, waive = parse_notes(notes)

            if math.isnan(base_amount):
                net = float('nan')
            else:
                net = base_amount * (1 + adj_pct / 100.0) + fee_val
                if waive:
                    net = 0.0

            rows.append({
                'record_id': record_id,
                'event_time': et,
                'event_time_raw': event_time_raw,
                'region': region,
                'channel': channel,
                'base_amount': base_amount,
                'items': items_val,
                'adj_pct': adj_pct,
                'fee': fee_val,
                'waive': waive,
                'net': net,
                'row_idx': idx,
            })

    groups = {}
    for r in rows:
        rid = r['record_id']
        if rid not in groups:
            groups[rid] = []
        groups[rid].append(r)

    deduped = []
    for rid, recs in groups.items():
        def sort_key(r):
            if r['event_time'] is None:
                return (0,)
            return (1,)
        recs.sort(key=lambda r: (
            r['event_time'] if r['event_time'] is not None else datetime.min,
            -1 if not math.isnan(r['net']) else 0,
            -r['row_idx']
        ), reverse=True)
        deduped.append(recs[0])

    filtered = []
    for r in deduped:
        if r['event_time'] is None:
            continue
        et = r['event_time']
        if et < datetime(2025, 10, 1, 0, 0, 0, tzinfo=et.tzinfo) or et > datetime(2025, 12, 31, 23, 59, 59, tzinfo=et.tzinfo):
            continue
        if r['channel'] == 'phone':
            continue
        if not math.isfinite(r['net']):
            continue
        filtered.append(r)

    group_map = {}
    for r in filtered:
        month = r['event_time'].strftime('%Y-%m')
        key = (r['region'], month)
        if key not in group_map:
            group_map[key] = []
        group_map[key].append(r)

    for key, group in group_map.items():
        net_vals = [r['net'] for r in group]
        zs = robust_z_score(net_vals)
        for r, z in zip(group, zs):
            r['robust_z'] = z

    for r in filtered:
        if 'robust_z' not in r:
            r['robust_z'] = 0.0

    for r in filtered:
        items_eff = r['items'] if r['items'] is not None else 1
        items_eff = max(items_eff, 1)
        r['items_eff'] = items_eff
        r['anomaly_score'] = abs(r['robust_z']) * math.log1p(items_eff)

    sorted_rows = sorted(filtered, key=lambda r: (
        -r['anomaly_score'],
        -abs(r['robust_z']),
        -(r['event_time'].timestamp() if r['event_time'] else 0),
        r['record_id']
    ))

    top10 = [r['record_id'] for r in sorted_rows[:10]]
    return top10


if __name__ == '__main__':
    import json
    result = answer()
    with open('/app/answer.json', 'w') as f:
        json.dump(result, f, default=list)

